CREATE TABLE IF NOT EXISTS app_users (username VARCHAR(64) PRIMARY KEY, password VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL, display_name VARCHAR(200) NOT NULL, sensitive VARCHAR(2048));
CREATE TABLE IF NOT EXISTS documents (id BIGINT PRIMARY KEY, owner VARCHAR(64) NOT NULL, title VARCHAR(200) NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, author VARCHAR(64) NOT NULL, body VARCHAR(1000) NOT NULL);
